import icontract

@icontract.require(lambda a: a > 0)
@icontract.require(lambda b: b > 0)
@icontract.ensure(lambda a, result: a % result == 0)
@icontract.ensure(lambda b, result: b % result == 0)
@icontract.ensure(lambda result: result > 0)
def gcd(a: int, b: int) -> int:
    while b != 0:
        a, b = b, a % b
    return a
